/**
 * Host ports for the three Angular dev servers. They appear in no URL — the proxy fronts them by
 * hostname — but they are persisted and reused so that a restart does not move Vite's HMR endpoint.
 */

import { createConnection, createServer } from 'node:net';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { DEV_SERVERS } from './services.mjs';

const STATE_FILE = 'ports.json';
const LISTENING_CHECK_TIMEOUT_MS = 300;

// Decides by binding: only correct for unprivileged ports we can actually bind. A non-root
// process on macOS gets EACCES for any port below 1024 regardless of whether it is occupied, so
// this must never be used to probe a privileged port like the proxy's 80/443 — use
// isPortListening for that instead. Do not "simplify" the two into one function.
export function isPortFree(port) {
  return new Promise((resolve) => {
    const server = createServer();
    server.once('error', () => resolve(false));
    server.once('listening', () => server.close(() => resolve(true)));
    server.listen(port, '127.0.0.1');
  });
}

// Decides by connecting: works at any privilege level, including privileged ports a non-root
// process could never bind. Resolves true only when something actually accepts the connection.
export function isPortListening(port) {
  return new Promise((resolve) => {
    const socket = createConnection({ port, host: '127.0.0.1', timeout: LISTENING_CHECK_TIMEOUT_MS });
    const settle = (listening) => {
      socket.destroy();
      resolve(listening);
    };
    socket.once('connect', () => settle(true));
    socket.once('timeout', () => settle(false));
    socket.once('error', () => settle(false));
  });
}

export function allocatePort() {
  return new Promise((resolve, reject) => {
    const server = createServer();
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      const { port } = server.address();
      server.close(() => resolve(port));
    });
  });
}

export async function resolveDevServerPorts(stateDir) {
  const stored = readState(join(stateDir, STATE_FILE));
  const taken = new Set();
  const ports = {};

  for (const { name } of DEV_SERVERS) {
    const candidate = stored[name];
    if (Number.isInteger(candidate) && !taken.has(candidate) && (await isPortFree(candidate))) {
      ports[name] = candidate;
    } else {
      ports[name] = await allocateUnused(taken);
    }
    taken.add(ports[name]);
  }

  mkdirSync(stateDir, { recursive: true });
  writeFileSync(join(stateDir, STATE_FILE), `${JSON.stringify(ports, null, 2)}\n`);
  return ports;
}

async function allocateUnused(taken) {
  let port = await allocatePort();
  while (taken.has(port)) {
    port = await allocatePort();
  }
  return port;
}
